{
  "sop_id": "SOP-018",
  "title": "Daily Ops Report",
  "steps": [
    {
      "step_id": "S1",
      "name": "Create report ticket",
      "role": "Executor",
      "type": "intake"
    },
    {
      "step_id": "S2",
      "name": "Pull production, downtime, and manpower numbers from all sites",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S3",
      "name": "Reconcile numbers against plan and calculate KPIs",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S4",
      "name": "Log incidents, deviations, and actions taken",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S5",
      "name": "Compile the report",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S6",
      "name": "Publish the report",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "A1",
      "name": "Incharge review and approval",
      "role": "Incharge",
      "type": "approval"
      },
      {
        "step_id": "D1",
        "name": "Decision: Is there a KPI breach or safety event flagged?",
        "role": "System",
        "type": "decision"
      },
      {
        "step_id": "A1a",
        "name": "Incharge review and approval",
        "role": "Incharge",
        "type": "approval"
        },
      {
        "step_id": "R1",
        "name": "Executor fixes the report based on rejection reasons and republishes",
        "role": "Executor",
        "type": "rework"
      }
  ],
  "approvals": [
    {
      "stage": "Incharge",
      "condition": "only if a KPI breach or safety event is flagged"
    }
  ],
  "dependencies": [],
  "rework_reasons": [
    "Wrong quantity",
    "Amount mismatch",
    "Incorrect category",
    "Required document missing"
  ],
  "first_pass_yield_target": 0.95
}
